package com.corp.member.service;

import com.corp.member.model.dto.CreateMemberRequest;
import com.corp.member.model.dto.MemberResponse;
import com.corp.member.model.entity.Member;
import com.corp.member.repository.MemberRepository;
import com.corp.member.service.impl.MemberServiceImpl;
import com.corp.member.exception.ResourceNotFoundException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class MemberServiceTest {

    @Mock
    private MemberRepository repository;

    @InjectMocks
    private MemberServiceImpl service;

    private Member entity;

    @BeforeEach
    void setUp() {
        entity = new Member();
        entity.setId(1L);
    }

    @Test
    void shouldCreateMemberSuccessfully() {
        CreateMemberRequest request = new CreateMemberRequest("user@example.com", "sample", 1, "sample");
        when(repository.save(any(Member.class))).thenReturn(entity);

        MemberResponse response = service.create(request);

        assertNotNull(response);
        assertEquals(1L, response.id());
        verify(repository, times(1)).save(any(Member.class));
    }

    @Test
    void shouldFindMemberByIdSuccessfully() {
        when(repository.findById(1L)).thenReturn(Optional.of(entity));

        MemberResponse response = service.findById(1L);

        assertNotNull(response);
        assertEquals(1L, response.id());
        verify(repository, times(1)).findById(1L);
    }

    @Test
    void shouldThrowExceptionWhenMemberNotFound() {
        when(repository.findById(99L)).thenReturn(Optional.empty());

        assertThrows(ResourceNotFoundException.class, () -> service.findById(99L));
        verify(repository, times(1)).findById(99L);
    }

    @Test
    void shouldFindAllMembers() {
        when(repository.findAll()).thenReturn(List.of(entity));

        List<MemberResponse> list = service.findAll();

        assertNotNull(list);
        assertEquals(1, list.size());
        verify(repository, times(1)).findAll();
    }

    @Test
    void shouldDeleteMemberSuccessfully() {
        when(repository.existsById(1L)).thenReturn(true);
        doNothing().when(repository).deleteById(1L);

        assertDoesNotThrow(() -> service.delete(1L));
        verify(repository, times(1)).deleteById(1L);
    }
}

