package com.corp.notes.service;

import com.corp.notes.model.dto.CreateNoteRequest;
import com.corp.notes.model.dto.NoteResponse;
import com.corp.notes.model.entity.Note;
import com.corp.notes.repository.NoteRepository;
import com.corp.notes.service.impl.NoteServiceImpl;
import com.corp.notes.exception.ResourceNotFoundException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class NoteServiceTest {

    @Mock
    private NoteRepository repository;

    @InjectMocks
    private NoteServiceImpl service;

    private Note entity;

    @BeforeEach
    void setUp() {
        entity = new Note();
        entity.setId(1L);
    }

    @Test
    void shouldCreateNoteSuccessfully() {
        CreateNoteRequest request = new CreateNoteRequest("sample");
        when(repository.save(any(Note.class))).thenReturn(entity);

        NoteResponse response = service.create(request);

        assertNotNull(response);
        assertEquals(1L, response.id());
        verify(repository, times(1)).save(any(Note.class));
    }

    @Test
    void shouldFindNoteByIdSuccessfully() {
        when(repository.findById(1L)).thenReturn(Optional.of(entity));

        NoteResponse response = service.findById(1L);

        assertNotNull(response);
        assertEquals(1L, response.id());
        verify(repository, times(1)).findById(1L);
    }

    @Test
    void shouldThrowExceptionWhenNoteNotFound() {
        when(repository.findById(99L)).thenReturn(Optional.empty());

        assertThrows(ResourceNotFoundException.class, () -> service.findById(99L));
        verify(repository, times(1)).findById(99L);
    }

    @Test
    void shouldFindAllNotes() {
        when(repository.findAll()).thenReturn(List.of(entity));

        List<NoteResponse> list = service.findAll();

        assertNotNull(list);
        assertEquals(1, list.size());
        verify(repository, times(1)).findAll();
    }

    @Test
    void shouldDeleteNoteSuccessfully() {
        when(repository.existsById(1L)).thenReturn(true);
        doNothing().when(repository).deleteById(1L);

        assertDoesNotThrow(() -> service.delete(1L));
        verify(repository, times(1)).deleteById(1L);
    }
}

