package com.corp.catalog.service.impl;

import com.corp.catalog.model.dto.CreateCategoryRequest;
import com.corp.catalog.model.dto.CategoryResponse;
import com.corp.catalog.model.entity.Category;
import com.corp.catalog.repository.CategoryRepository;
import com.corp.catalog.service.CategoryService;
import com.corp.catalog.exception.ResourceNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@Transactional
public class CategoryServiceImpl implements CategoryService {

    private final CategoryRepository repository;

    public CategoryServiceImpl(CategoryRepository repository) {
        this.repository = repository;
    }

    @Override
    public CategoryResponse create(CreateCategoryRequest request) {
        Category entity = new Category();
        entity.setTitle(request.title());
        entity.setCreatedAt(request.createdAt());
        entity.setDisplayOrder(request.displayOrder());
        Category saved = repository.save(entity);
        return CategoryResponse.fromEntity(saved);
    }

    @Override
    @Transactional(readOnly = true)
    public CategoryResponse findById(Long id) {
        Category entity = repository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Category not found with id: " + id));
        return CategoryResponse.fromEntity(entity);
    }

    @Override
    @Transactional(readOnly = true)
    public List<CategoryResponse> findAll() {
        return repository.findAll().stream()
                .map(CategoryResponse::fromEntity)
                .collect(Collectors.toList());
    }

    @Override
    public void delete(Long id) {
        if (!repository.existsById(id)) {
            throw new ResourceNotFoundException("Category not found with id: " + id);
        }
        repository.deleteById(id);
    }
}

