package com.corp.invoice.service;

import com.corp.invoice.model.dto.CreateInvoiceRequest;
import com.corp.invoice.model.dto.InvoiceResponse;
import com.corp.invoice.model.entity.Invoice;
import com.corp.invoice.repository.InvoiceRepository;
import com.corp.invoice.service.impl.InvoiceServiceImpl;
import com.corp.invoice.exception.ResourceNotFoundException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class InvoiceServiceTest {

    @Mock
    private InvoiceRepository repository;

    @InjectMocks
    private InvoiceServiceImpl service;

    private Invoice entity;

    @BeforeEach
    void setUp() {
        entity = new Invoice();
        entity.setId(1L);
    }

    @Test
    void shouldCreateInvoiceSuccessfully() {
        CreateInvoiceRequest request = new CreateInvoiceRequest("sample", new java.math.BigDecimal("1.00"));
        when(repository.save(any(Invoice.class))).thenReturn(entity);

        InvoiceResponse response = service.create(request);

        assertNotNull(response);
        assertEquals(1L, response.id());
        verify(repository, times(1)).save(any(Invoice.class));
    }

    @Test
    void shouldFindInvoiceByIdSuccessfully() {
        when(repository.findById(1L)).thenReturn(Optional.of(entity));

        InvoiceResponse response = service.findById(1L);

        assertNotNull(response);
        assertEquals(1L, response.id());
        verify(repository, times(1)).findById(1L);
    }

    @Test
    void shouldThrowExceptionWhenInvoiceNotFound() {
        when(repository.findById(99L)).thenReturn(Optional.empty());

        assertThrows(ResourceNotFoundException.class, () -> service.findById(99L));
        verify(repository, times(1)).findById(99L);
    }

    @Test
    void shouldFindAllInvoices() {
        when(repository.findAll()).thenReturn(List.of(entity));

        List<InvoiceResponse> list = service.findAll();

        assertNotNull(list);
        assertEquals(1, list.size());
        verify(repository, times(1)).findAll();
    }

    @Test
    void shouldDeleteInvoiceSuccessfully() {
        when(repository.existsById(1L)).thenReturn(true);
        doNothing().when(repository).deleteById(1L);

        assertDoesNotThrow(() -> service.delete(1L));
        verify(repository, times(1)).deleteById(1L);
    }
}

