package com.corp.invoice.service.impl;

import com.corp.invoice.model.dto.CreateInvoiceRequest;
import com.corp.invoice.model.dto.InvoiceResponse;
import com.corp.invoice.model.entity.Invoice;
import com.corp.invoice.repository.InvoiceRepository;
import com.corp.invoice.service.InvoiceService;
import com.corp.invoice.exception.ResourceNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@Transactional
public class InvoiceServiceImpl implements InvoiceService {

    private final InvoiceRepository repository;

    public InvoiceServiceImpl(InvoiceRepository repository) {
        this.repository = repository;
    }

    @Override
    public InvoiceResponse create(CreateInvoiceRequest request) {
        Invoice entity = new Invoice();
        entity.setCustomerEmail(request.customerEmail());
        entity.setAmount(request.amount());
        Invoice saved = repository.save(entity);
        return InvoiceResponse.fromEntity(saved);
    }

    @Override
    @Transactional(readOnly = true)
    public InvoiceResponse findById(Long id) {
        Invoice entity = repository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Invoice not found with id: " + id));
        return InvoiceResponse.fromEntity(entity);
    }

    @Override
    @Transactional(readOnly = true)
    public List<InvoiceResponse> findAll() {
        return repository.findAll().stream()
                .map(InvoiceResponse::fromEntity)
                .collect(Collectors.toList());
    }

    @Override
    public void delete(Long id) {
        if (!repository.existsById(id)) {
            throw new ResourceNotFoundException("Invoice not found with id: " + id);
        }
        repository.deleteById(id);
    }
}

